import{_ as i,a as n,c as l,ac as a}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第四册：流利英语 · 单元 5：范围、变化与公共论证","description":"L33–L40 的学习目标、课时入口和复习方法。","frontmatter":{"title":"第四册：流利英语 · 单元 5：范围、变化与公共论证","description":"L33–L40 的学习目标、课时入口和复习方法。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","summary":"L33–L40 的学习目标、课时入口和复习方法。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 4 复习与自测","link":"/life/english/new-concept/book-4/unit-04/review"},"next":{"text":"第四册：流利英语 · 单元 5 语法总结","link":"/life/english/new-concept/book-4/unit-05/grammar"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 4 复习与自测","link":"/life/english/new-concept/book-4/unit-04/review"},"next":{"text":"第四册：流利英语 · 单元 5 语法总结","link":"/life/english/new-concept/book-4/unit-05/grammar"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-05/overview.md","filePath":"life/english/new-concept/book-4/unit-05/overview.md"}'),o={name:"life/english/new-concept/book-4/unit-05/overview.md"};function t(r,e,s,c,h,p){return n(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="第四册-流利英语-·-单元-5-范围、变化与公共论证" tabindex="-1">第四册：流利英语 · 单元 5：范围、变化与公共论证 <a class="header-anchor" href="#第四册-流利英语-·-单元-5-范围、变化与公共论证" aria-label="Permalink to &quot;第四册：流利英语 · 单元 5：范围、变化与公共论证&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-05/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-05/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-05/review">单元复习与自测</a></p><h2 id="单元导读" tabindex="-1">单元导读 <a class="header-anchor" href="#单元导读" aria-label="Permalink to &quot;单元导读&quot;">​</a></h2><p>L33–L40。第33—40课讨论教育、青春期、太空计划、公共支出、渐进变化、旅行信息、写作愿望和波浪。训练把宏观观点落实为目标、时间、单位和范围，尤其避免群体概括抹去个体差异。数字练习需要真正计算，预测练习需要明确截止点，历史实用信息需要核查时效。用平行结构与准确连接让论证便于比较和复核。</p><p>本栏目按连续课号组织学习单元；单元主题与复习任务为本站编排，便于分阶段学习，不作为各印次教材目录的替代。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>写出可观察的教育和研究目标</li><li>准确表达倍数、百分比与渐变</li><li>区分愿望、计划和完成预测</li></ul><h2 id="课时目录" tabindex="-1">课时目录 <a class="header-anchor" href="#课时目录" aria-label="Permalink to &quot;课时目录&quot;">​</a></h2><ul><li><a href="/life/english/new-concept/book-4/unit-05/lesson-033">Lesson 33 · Education</a></li><li><a href="/life/english/new-concept/book-4/unit-05/lesson-034">Lesson 34 · Adolescence</a></li><li><a href="/life/english/new-concept/book-4/unit-05/lesson-035">Lesson 35 · Space odyssey</a></li><li><a href="/life/english/new-concept/book-4/unit-05/lesson-036">Lesson 36 · The cost of government</a></li><li><a href="/life/english/new-concept/book-4/unit-05/lesson-037">Lesson 37 · The process of ageing</a></li><li><a href="/life/english/new-concept/book-4/unit-05/lesson-038">Lesson 38 · Water and the traveller</a></li><li><a href="/life/english/new-concept/book-4/unit-05/lesson-039">Lesson 39 · What every writer wants</a></li><li><a href="/life/english/new-concept/book-4/unit-05/lesson-040">Lesson 40 · Waves</a></li></ul><h2 id="单元知识地图" tabindex="-1">单元知识地图 <a class="header-anchor" href="#单元知识地图" aria-label="Permalink to &quot;单元知识地图&quot;">​</a></h2><ul><li>L33：平行结构与 not only…but also。to question claims, comparing sources and explanations 不平行；应统一为三个动词短语。</li><li>L34：倾向表达与概率范围。tend to 不等于 always；不能将示例改写成“所有青少年都只向同伴求助”。</li><li>L35：将来完成时与未来截止点。by the time the crew will arrive 不用于普通未来时间从句；应使用 arrives。</li><li>L36：倍数比较与百分比基数。rose by 120 units 不等于 rose to 120 units；本例只增加20单位。</li><li>L37：比较级重复与渐变表达。more and more better 不成立；better 已是比较级，应写 better and better。</li><li>L38：if、when 后的省略结构。When travelling, the water… 容易把 travelling 的执行者错接成 water；应明确人作主语。</li><li>L39：wish 后的时态与非现实意义。不要把对现有稿件的遗憾写成 wish the opening is shorter；此处需要过去形式表达非现实。</li><li>L40：where 的地点与条件意义。不要把“实验结束时”写成 where the experiment ends；普通时间关系应写 when the experiment ends。</li></ul><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>能用自己的例子说明上面的语法点；能在不看答案时完成单元自测；能完成至少一项口头表达和一项书面表达，并根据课时点评修订。若做错，不必整单元重学，沿题目链接回到相应课时。</p>',13)])])}const f=i(o,[["render",t]]);export{d as __pageData,f as default};
